package com.picviewer.app;

import android.content.Context;import android.graphics.*;import android.view.*;import android.widget.ImageView;

/** Presentation only. All images remain sampled; zoom never requests a full-size RAW. */
final class FrameImageView extends ImageView {
 float zoom=1,panX,panY,lastX,lastY,downX,downY;boolean multi=false,scaled=false,blurMode=false,fade=false;long fadeStart;
 Bitmap previous,backdrop;final Rect backdropRect=new Rect();final RectF transitionRect=new RectF();final Paint paint=new Paint(3);final ScaleGestureDetector scaling;final GestureDetector gestures;MainActivity owner;
 FrameImageView(MainActivity a){super(a);owner=a;scaling=new ScaleGestureDetector(a,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){setZoom(zoom*d.getScaleFactor());multi=true;return true;}});gestures=new GestureDetector(a,new GestureDetector.SimpleOnGestureListener(){public boolean onDown(MotionEvent e){return true;}public boolean onDoubleTap(MotionEvent e){setZoom(zoom>1?1:2);scaled=true;return true;}});}
 void setZoom(float value){zoom=Math.max(1,Math.min(4,value));if(zoom==1){panX=panY=0;}else if(owner.playing){if(owner.viewing!=null)owner.viewing.userPause();if(!owner.paused)owner.togglePause();}clamp();invalidate();}
 void clamp(){float x=getWidth()*(zoom-1)/2,y=getHeight()*(zoom-1)/2;panX=Math.max(-x,Math.min(x,panX));panY=Math.max(-y,Math.min(y,panY));}
 void configure(boolean blur,boolean transition,boolean crop){blurMode=blur;fade=transition;setScaleType(crop?ScaleType.CENTER_CROP:ScaleType.FIT_CENTER);buildBackdrop();invalidate();}
 void discardPrevious(){if(previous!=null){previous.recycle();previous=null;}}
 @Override public void setImageBitmap(Bitmap bitmap){discardPrevious();if(fade&&owner.shown!=null&&!owner.shown.isRecycled()&&owner.frameBudget()>12*NextFrame.MIB&&getDrawable()!=null){try{android.graphics.drawable.Drawable d=getDrawable();if(d instanceof android.graphics.drawable.BitmapDrawable){Bitmap old=((android.graphics.drawable.BitmapDrawable)d).getBitmap();if(old!=bitmap&&!old.isRecycled())previous=old.copy(Bitmap.Config.ARGB_8888,false);}}catch(OutOfMemoryError ignored){previous=null;}}
  fadeStart=android.os.SystemClock.uptimeMillis();zoom=1;panX=panY=0;super.setImageBitmap(bitmap);buildBackdrop();}
 void buildBackdrop(){if(backdrop!=null){backdrop.recycle();backdrop=null;}if(!blurMode||!(getDrawable() instanceof android.graphics.drawable.BitmapDrawable))return;Bitmap b=((android.graphics.drawable.BitmapDrawable)getDrawable()).getBitmap();if(b==null||b.isRecycled())return;try{Bitmap tiny=Bitmap.createScaledBitmap(b,24,24,true);backdrop=tiny.copy(Bitmap.Config.ARGB_8888,true);if(tiny!=b)tiny.recycle();int[] px=new int[576];backdrop.getPixels(px,0,24,0,0,24,24);int[] out=px.clone();for(int y=0;y<24;y++)for(int x=0;x<24;x++){int r=0,g=0,bl=0,n=0;for(int j=Math.max(0,y-2);j<=Math.min(23,y+2);j++)for(int i=Math.max(0,x-2);i<=Math.min(23,x+2);i++){int c=px[j*24+i];r+=Color.red(c);g+=Color.green(c);bl+=Color.blue(c);n++;}out[y*24+x]=Color.rgb(r/n,g/n,bl/n);}backdrop.setPixels(out,0,24,0,0,24,24);}catch(OutOfMemoryError ignored){backdrop=null;}}
 @Override protected void onDraw(Canvas c){if(backdrop!=null&&!backdrop.isRecycled()){paint.setAlpha(140);backdropRect.set(0,0,getWidth(),getHeight());c.drawBitmap(backdrop,null,backdropRect,paint);paint.setAlpha(255);}float progress=Math.min(1,(android.os.SystemClock.uptimeMillis()-fadeStart)/320f);if(previous!=null&&!previous.isRecycled()&&progress<1){paint.setAlpha(255);float s=getScaleType()==ScaleType.CENTER_CROP?Math.max((float)getWidth()/previous.getWidth(),(float)getHeight()/previous.getHeight()):Math.min((float)getWidth()/previous.getWidth(),(float)getHeight()/previous.getHeight());float w=previous.getWidth()*s,h=previous.getHeight()*s;transitionRect.set((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2);c.drawBitmap(previous,null,transitionRect,paint);}int save=c.save();c.translate(panX,panY);c.scale(zoom,zoom,getWidth()/2f,getHeight()/2f);if(previous!=null&&progress<1)c.saveLayerAlpha(0,0,getWidth(),getHeight(),(int)(255*progress));super.onDraw(c);c.restoreToCount(save);if(previous!=null){if(progress<1)postInvalidateOnAnimation();else discardPrevious();}}
 @Override public boolean onTouchEvent(MotionEvent e){scaling.onTouchEvent(e);gestures.onTouchEvent(e);if(e.getActionMasked()==MotionEvent.ACTION_DOWN){lastX=downX=e.getX();lastY=downY=e.getY();multi=false;scaled=false;}if(e.getPointerCount()>1)multi=true;if(e.getActionMasked()==MotionEvent.ACTION_MOVE&&zoom>1&&e.getPointerCount()==1){panX+=e.getX()-lastX;panY+=e.getY()-lastY;clamp();invalidate();}lastX=e.getX();lastY=e.getY();if(e.getActionMasked()==MotionEvent.ACTION_UP&&!multi&&!scaled){if(zoom==1&&Math.abs(e.getX()-downX)>owner.dp(75))owner.advance(e.getX()>downX);else if(Math.abs(e.getX()-downX)<owner.dp(12)&&Math.abs(e.getY()-downY)<owner.dp(12))performClick();}return true;}
 @Override public boolean performClick(){super.performClick();return true;}
 void release(){discardPrevious();if(backdrop!=null){backdrop.recycle();backdrop=null;}}
}
